const empty=(title,subtitle,ico='board')=>`<div class="empty">${icon(ico)}<strong>${title}</strong>${subtitle}</div>`;
const cats=id=>CATEGORIES.find(c=>c.id===id)||{id:'rv',name:'Renda variável · legado',color:'#a2836b',soft:'#f2ede7',icon:'history'};
