  const focused=document.activeElement, id=focused?.id, cursor=focused?.selectionStart;
  const boardX=$('.board')?.scrollLeft||0, scrolls=[...document.querySelectorAll('.column-body')].map(e=>e.scrollTop);
  if(!store&&!demo){renderWelcome();return;}
  const navs=[['board','Pipes','board'],['clients','Clientes','users'],['goals','Metas','target'],['agenda','Agenda','calendar'],['history','Histórico','history'],['settings','Minha base','settings']];
  const current=navs.find(n=>n[0]===screen)?.[1]||'Cliente';
  app.innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="eyebrow">Meu espaço de trabalho</div><nav class="nav-items" aria-label="Navegação principal">${navs.map(([key,name,ico])=>`<button class="nav-item ${screen===key?'active':''}" data-nav="${key}" title="${name}" aria-label="${name}" ${screen===key?'aria-current="page"':''}>${icon(ico)}<span>${name}</span>${key==='clients'?`<span class="nav-count">${values(state,'clients').length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-footer"><div class="private-note">${icon('shield')}<span>Seu relacionamento.<br>Sua visão completa.</span></div><div class="account"><div class="avatar">GA</div><div>Gustavo Amorim<small>${demo?'Base demonstrativa':'Espaço pessoal'}</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Meu workspace ${icon('chevron')} <b>${clientId&&screen==='clients'?'Visão do cliente':current}</b></div><div class="topbar-actions"><span class="sync ${syncStatus}" data-sync><i class="dot"></i>${statusLabel()}</span><button class="icon-btn" title="Bloquear base" aria-label="Bloquear base" data-action="lock">${icon('lock')}</button><span class="avatar">GA</span></div></header><div class="content">${demo?`<div class="notice demo">${icon('shield')}<span><strong>Demonstração com dados fictícios.</strong> As alterações aqui não vão para sua base.</span>${button('Abrir minha base','lock','','')}</div>`:''}${screen==='board'?renderBoard():screen==='clients'?clientId?renderClient():renderClients():screen==='goals'?renderGoals():screen==='agenda'?renderAgenda():screen==='history'?renderHistory():renderSettings()}</div></main></div>`;
