function pageTitle(title,subtitle,actions='',eyebrow='RELACIONAMENTO EM MOVIMENTO'){return `<div class="page-title"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="title-actions">${actions}</div></div>`;}
function metric(label,value,sub,ico='wallet'){return `<div class="metric"><span class="metric-icon">${icon(ico)}</span><span class="eyebrow">${label}</span><strong>${value}</strong><small>${sub}</small></div>`;}
function filtersHTML(clientMode=false){return `<div class="toolbar"><label class="search">${icon('search')}<input id="search" type="search" aria-label="Buscar cliente ou oportunidade" placeholder="${clientMode?'Buscar cliente…':'Buscar cliente ou oportunidade…'}" value="${esc(search)}"></label><div class="chips">${(clientMode?[['all','Todos'],['A','Classe A'],['B','Classe B'],['C','Classe C'],['D','Classe D'],['none','A classificar']]:[['all','Todos'],['A','A · Quentes'],['B','B · Mornos'],['C','C · Frios']]).map(([v,t])=>`<button class="chip ${filter===v?'on':''}" data-filter="${v}">${t}</button>`).join('')}</div>${!clientMode?`<span class="toolbar-spacer"></span><select id="dateFilter" class="select-small" aria-label="Filtrar por prazo">${options([{id:'all',name:'Todas as datas'},{id:'today',name:'Hoje e atrasados'},{id:'week',name:'Próximos 7 dias'},{id:'month',name:'Este mês'},{id:'none',name:'Sem data'}],dateFilter)}</select><select id="subtypeFilter" class="select-small" aria-label="Filtrar subtipo de captação">${options([{id:'all',name:'Todos os subtipos'},...SUBTYPES.map(x=>({id:x,name:x}))],subtypeFilter)}</select>`:`<select id="clientPotential" class="select-small" aria-label="Filtrar potencial do cliente">${options([{id:'all',name:'Todos os potenciais'},...CATEGORIES],clientPotential)}</select>`}</div>`;}
function matchPipe(p){
  if(!active(p))return false;
  if(filter!=='all'&&rank(p.nota)!==filter)return false;
  if(search&&!`${clientName(p)} ${p.title||''} ${p.notes||''}`.toLowerCase().includes(search.toLowerCase()))return false;
  if(subtypeFilter!=='all'&&p.cat==='cap'&&(p.subtype||'Outros')!==subtypeFilter)return false;
  const end=new Date(today()+'T12:00:00');end.setDate(end.getDate()+7);
  if(dateFilter==='today'&&(!p.date||p.date>today()))return false;
  if(dateFilter==='week'&&(!p.date||p.date<today()||p.date>end.toISOString().slice(0,10)))return false;
  if(dateFilter==='month'&&String(p.date).slice(0,7)!==today().slice(0,7))return false;
  if(dateFilter==='none'&&p.date)return false;
  return true;
}
function pipeCard(p){const r=rank(p.nota),cat=cats(p.cat);return `<article class="pipe-card" data-pipe="${esc(p.id)}"><button class="grip" data-drag="${esc(p.id)}" aria-label="Mover pipe de ${esc(clientName(p))}" title="Arraste ou toque para mover">${icon('grip')}</button><div class="card-content"><button class="card-client" data-client="${esc(p.clientId)}"><span class="avatar">${initials(clientName(p))}</span><span>${esc(clientName(p))}</span></button><div class="card-title">${esc(p.title||p.subtype||cat.name)}</div><div class="card-value">${shortMoney(p.value)}</div><div class="card-meta"><span class="pill rank-${r}">${r} · ${r==='A'?'Quente':r==='B'?'Morno':'Frio'}</span><span class="stage">${esc(p.stage)}</span></div><div class="card-next">${icon('arrow')}<span>${esc(p.next||'Definir próximo passo')}</span></div><div class="card-bottom"><span class="${p.date&&p.date<today()?'overdue':''}">${dateLabel(p.date)}${weight(p)>1?' · 1,25×':''}</span><button data-edit-pipe="${esc(p.id)}" aria-label="Editar pipe de ${esc(clientName(p))}">Detalhes ↗</button></div></div></article>`;}
function renderBoard(){const all=values(state,'pipes').filter(active), total=all.reduce((n,p)=>n+p.value,0), hot=all.filter(p=>rank(p.nota)==='A'), due=all.filter(p=>p.date&&p.date<=today());
  return pageTitle('Oportunidades que avançam.','Cada pipe, um próximo passo no relacionamento.',button('Novo cliente','new-client','users')+button('Novo pipe','new-pipe','plus','primary'))+
    `<div class="metrics">${metric('Pipeline em aberto',shortMoney(total),`${all.length} oportunidades em movimento`,'arrow')}${metric('Clientes com pipes',new Set(all.map(p=>p.clientId)).size,`${values(state,'clients').length} clientes na sua base`,'users')}${metric('Potencial quente',shortMoney(hot.reduce((n,p)=>n+p.value,0)),`${hot.length} pipes com prioridade A`,'target')}${metric('Próximos contatos',due.length,'Para hoje e em atraso','calendar')}</div>${filtersHTML()}<div class="board" aria-label="Quadro de oportunidades">${CATEGORIES.map(cat=>{const ps=values(state,'pipes').filter(p=>p.cat===cat.id&&matchPipe(p)).sort((a,b)=>(a.order??0)-(b.order??0)||(b.nota-a.nota));return `<section class="column" data-drop="${cat.id}" aria-label="${cat.name}"><div class="column-head"><span style="color:${cat.color}">${icon(cat.icon)}</span><h3>${cat.name}</h3><span class="count">${ps.length}</span><button class="icon-btn" data-new-cat="${cat.id}" aria-label="Novo pipe em ${cat.name}">${icon('plus')}</button></div><div class="column-sum">${shortMoney(ps.reduce((n,p)=>n+p.value,0))} em oportunidades</div><div class="column-body">${ps.length?ps.map(pipeCard).join(''):empty('Espaço para oportunidades','Adicione um pipe ou arraste para cá.','plus')}</div><button class="column-add" data-new-cat="${cat.id}">${icon('plus')}Adicionar oportunidade</button></section>`;}).join('')}</div><p class="board-hint">${icon('grip')}Arraste pela alça para mudar de categoria, concluir ou levar à lixeira. Toque na alça para abrir as mesmas opções.</p>`;
}
function renderClients(){const cs=values(state,'clients').filter(c=>(!search||`${c.name} ${c.notes||''}`.toLowerCase().includes(search.toLowerCase()))&&(filter==='all'||(filter==='none'?!c.tier:c.tier===filter))&&(clientPotential==='all'||(c.potentials?.[clientPotential]&&c.potentials[clientPotential]!=='Sem potencial'&&c.potentials[clientPotential]!=='A mapear'))).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));
  const allAssets=values(state,'assets'),external=allAssets.filter(a=>!ricoAsset(a)).reduce((n,a)=>n+a.value,0);
  return pageTitle('Pessoas antes dos números.','Uma visão completa de cada cliente, dentro e fora da Rico.',button('Novo cliente','new-client','plus','primary'),'SUA BASE DE RELACIONAMENTOS')+`<div class="metrics">${metric('Patrimônio mapeado',shortMoney(assetTotal()),'Valores informados por você')}${metric('Clientes cadastrados',values(state,'clients').length,'Todos em uma única base','users')}${metric('Na Rico',shortMoney(allAssets.filter(ricoAsset).reduce((n,a)=>n+a.value,0)),'Patrimônio sob relacionamento','pie')}${metric('Outras instituições',shortMoney(external),'Visibilidade para novas conversas','arrow')}</div>${filtersHTML(true)}<div class="panel client-list">${cs.length?`<table class="table"><thead><tr><th>Cliente</th><th>Classe</th><th>Patrimônio mapeado</th><th>Potenciais</th><th>Pipes abertos</th><th></th></tr></thead><tbody>${cs.map(c=>`<tr><td><button class="client-name" data-client="${esc(c.id)}"><span class="avatar">${initials(c.name)}</span><span>${esc(c.name)}<small>${esc(c.profile||'Perfil não informado')}</small></span></button></td><td><span class="pill tier-${esc(c.tier||'none')}">${esc(c.tier||'A classificar')}</span></td><td class="money">${assetTotal(c.id)?money(assetTotal(c.id)):'Ainda não informado'}</td><td><div class="tags">${CATEGORIES.filter(cat=>c.potentials?.[cat.id]&&c.potentials[cat.id]!=='Sem potencial').map(cat=>`<span class="pill" style="color:${cat.color};background:${cat.soft}">${cat.name} · ${esc(c.potentials[cat.id])}</span>`).join('')||'<span class="muted">A mapear</span>'}</div></td><td>${values(state,'pipes').filter(p=>p.clientId===c.id&&active(p)).length}</td><td><button class="icon-btn" data-client="${esc(c.id)}" aria-label="Abrir ${esc(c.name)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table>`:empty('Sua base começa com uma pessoa.','Cadastre um cliente ou importe seus pipes antigos.','users')}</div>`;
}
function renderClient(){const c=state.clients[clientId];if(!c){clientId=null;return renderClients();}
  const assets=values(state,'assets').filter(a=>a.clientId===c.id),pipes=values(state,'pipes').filter(p=>p.clientId===c.id),total=assets.reduce((n,a)=>n+a.value,0),rico=assets.filter(ricoAsset).reduce((n,a)=>n+a.value,0);
  const groups={};for(const a of assets){const k=groupWallet==='class'?classLabel(a.class):a.institution;groups[k]=(groups[k]||0)+a.value;}
  const sorted=Object.entries(groups).sort((a,b)=>b[1]-a[1]);let angle=0;const stops=sorted.map(([k,v],i)=>{const start=angle;angle+=total?v/total*100:0;return `${COLORS[i%COLORS.length]} ${start}% ${angle}%`;});
  return `<button class="row muted small" data-action="back-clients">${icon('back')}Todos os clientes</button><div class="page-title" style="margin-top:14px"><div class="client-heading"><div class="avatar big">${initials(c.name)}</div><div><div class="eyebrow">SEU RELACIONAMENTO, POR INTEIRO</div><h1>${esc(c.name)} <span class="pill tier-${esc(c.tier||'none')}">${c.tier?'Classe '+esc(c.tier):'A classificar'}</span></h1><p>${esc(c.profile||'Perfil não informado')}${c.phone?' · '+esc(c.phone):''}</p></div></div><div class="title-actions">${button('Editar cliente','edit-client','edit')}${button('Novo pipe','client-pipe','plus','primary')}</div></div><div class="detail-grid"><section class="panel"><div class="panel-head"><h3>Carteira consolidada</h3><div class="segment"><button data-group="class" class="${groupWallet==='class'?'on':''}">Por classe</button><button data-group="institution" class="${groupWallet==='institution'?'on':''}">Por instituição</button></div></div><div class="donut-layout"><div class="donut" role="img" aria-label="Patrimônio total ${money(total)}. ${esc(sorted.map(([k,v])=>`${k}: ${money(v)}`).join('; '))}" style="background:${total?'conic-gradient('+stops.join(',')+')':'#edf0e7'}"><div class="donut-hole"><small>PATRIMÔNIO TOTAL</small><strong>${shortMoney(total)}</strong><small>${assets.length} posições informadas</small></div></div><div class="legend">${sorted.length?sorted.map(([k,v],i)=>`<div class="legend-row"><i class="dot" style="color:${COLORS[i%COLORS.length]}"></i><span>${esc(k)}</span><strong>${(v/total*100).toLocaleString('pt-BR',{maximumFractionDigits:1})}%</strong></div>`).join(''):'<p class="muted">Cadastre a carteira na Rico e os valores em outros bancos para ver a distribuição.</p>'}</div></div><div class="wallet-foot"><span>Na Rico<b>${money(rico)}</b></span><span>Outras instituições<b>${money(total-rico)}</b></span></div></section><section class="panel"><div class="panel-head"><h3>Mapa de potencial</h3><button class="icon-btn" data-action="edit-client" aria-label="Editar potenciais">${icon('edit')}</button></div><div class="potential-list">${CATEGORIES.map(cat=>`<div class="potential-item"><div class="row"><span style="color:${cat.color}">${icon(cat.icon)}</span><div>${cat.name}<small>${pipes.filter(p=>p.cat===cat.id&&active(p)).length} pipes em aberto</small></div></div><span class="potential-level">${esc(c.potentials?.[cat.id]||'A mapear')}</span></div>`).join('')}</div></section></div><div class="detail-tabs">${[['wallet','Posições da carteira'],['pipes','Oportunidades'],['notes','Sobre o cliente']].map(([v,t])=>`<button data-tab="${v}" class="${detailTab===v?'on':''}">${t}</button>`).join('')}</div>${detailTab==='wallet'?`<div class="panel"><div class="panel-head"><div><h3>Dentro e fora da Rico</h3><p class="muted small" style="margin-top:5px">Registre um saldo geral ou detalhe por investimento.</p></div>${button('Adicionar posição','new-asset','plus')}</div><div class="client-list">${assets.length?`<table class="table"><thead><tr><th>Instituição / investimento</th><th>Classe</th><th>Valor informado</th><th>Atualização</th><th></th></tr></thead><tbody>${assets.map(a=>`<tr><td><b>${esc(a.institution)}</b><div class="muted small" style="margin-top:4px">${esc(a.name||'Saldo informado')}</div></td><td>${esc(classLabel(a.class))}</td><td class="money">${money(a.value)}</td><td>${dateLabel(a.asOf)}</td><td><button class="icon-btn" data-edit-asset="${esc(a.id)}" aria-label="Editar posição ${esc(a.name||a.institution)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table>`:empty('Uma carteira, todas as instituições.','Exemplo: C6 · Saldo informado · R$ 200.000.','wallet')}</div></div>`:detailTab==='pipes'?`<div class="panel">${pipes.length?pipes.map(activityRow).join(''):empty('Nenhum pipe para este cliente.','Crie a primeira oportunidade de relacionamento.','board')}</div>`:`<div class="panel panel-pad stack"><h3>Contexto do relacionamento</h3><p class="notes">${esc(c.notes||'Adicione objetivos, preferências e o que você quer lembrar na próxima conversa.')}</p><p class="muted small">${esc(c.email||'E-mail não informado')}${c.phone?' · '+esc(c.phone):''}</p>${button('Editar informações','edit-client','edit')}</div>`}`;
}
function activityRow(p){const cat=cats(p.cat);return `<div class="activity"><span style="color:${cat.color}">${icon(cat.icon)}</span><div><strong>${esc(p.title||cat.name)} · ${esc(clientName(p))}</strong><p>${esc(p.outcome||(p.retired?'Legado preservado':p.deletedAt?'Na lixeira':p.snoozeUntil&&p.snoozeUntil>today()?'Adiado até '+dateLabel(p.snoozeUntil):p.stage))} · ${dateLabel(p.date)}</p></div><div class="right"><strong>${shortMoney(p.value)}</strong><p>${cat.name}</p></div><button class="icon-btn" data-edit-pipe="${esc(p.id)}" aria-label="Detalhes do pipe ${esc(clientName(p))}">${icon('chevron')}</button></div>`;}
function renderGoals(){const m=monthData(state,month),g=state.settings.goals;
  return pageTitle('Clareza para chegar lá.','Suas metas mensais, com as regras do seu pipeline.',`<input type="month" id="goalMonth" value="${month}" aria-label="Mês das metas" class="select-small">${button('Ajustar metas','edit-goals','edit')}`,'RESULTADO & DIREÇÃO')+`<section class="panel mereo"><div class="mereo-score"><span class="eyebrow">MEREO · MÊS</span><strong>${m.score.toFixed(2).replace('.',',')}</strong><span class="small muted">de 5,00</span></div><div class="mereo-components">${m.components.map(c=>`<div class="mereo-component">${c.name} · ${c.weight*100}%<b>${c.score.toFixed(1).replace('.',',')}</b><span>${c.unit===undefined?shortMoney(c.value):Number(c.value).toLocaleString('pt-BR',{maximumFractionDigits:1})+' '+c.unit}${c.assumed?' · referência':''}</span></div>`).join('')}</div></section><div class="row between" style="margin-bottom:18px"><p class="small muted">${monthLabel()} · Previdência/STVM na captação: 1,25×</p>${button('Lançar realizado','edit-results','plus')}</div><div class="goal-grid">${CATEGORIES.map(cat=>{const key=cat.id==='ag'?'aloc':cat.id,real=m.realized[key],target=g[key]||0,pct=target>0?real/target*100:0,p=m.pipeline[cat.id],a=real+p.a,b=a+p.b,cc=b+p.c;return `<section class="panel goal-card"><div class="goal-top"><div class="row"><span style="color:${cat.color}">${icon(cat.icon)}</span><h3>${cat.name}</h3></div><span class="pill" style="color:${cat.color};background:${cat.soft}">${Math.round(pct)}%</span></div><div class="goal-number">${shortMoney(real)} <small>de ${shortMoney(target)}</small></div><p class="small muted">Realizado no mês</p><div class="progress"><span style="width:${Math.min(pct,100)}%;background:${cat.color}"></span></div><p class="small muted">${real>=target?'Meta alcançada':'Faltam '+shortMoney(Math.max(0,target-real))}</p><div class="scenarios"><span>Realizado + A<b>${shortMoney(a)}</b></span><span>+ A e B<b>${shortMoney(b)}</b></span><span>+ A, B e C<b>${shortMoney(cc)}</b></span></div></section>`;}).join('')}</div><p class="small muted" style="margin:20px 0;line-height:1.8">Os cenários incluem pipes previstos para o mês. MEREO mantém os pesos originais e a cesta de investimento de R$ 2,2 mi; inclui Previdência ponderada e os resultados históricos de RV. Crossell: cartão = 1 ponto, consórcio = 1 ponto/R$ 10 mil, seguro = 1 ponto/R$ 1 mil. NPS e índice comercial usam referências anteriores até você lançar o resultado.</p>`;
}
function renderAgenda(){const base=new Date(today()+'T12:00:00');base.setDate(base.getDate()-((base.getDay()+6)%7)+weekOffset*7);const days=Array.from({length:7},(_,i)=>{const d=new Date(base);d.setDate(d.getDate()+i);return d;});
  return pageTitle('Uma boa conversa começa aqui.','Próximos passos da semana, ligados a cada cliente.',button('Anterior','week-prev','back')+button('Hoje','week-today')+button('Próxima','week-next','chevron'),'AGENDA DE RELACIONAMENTO')+`<div class="week-grid">${days.map(d=>{const date=d.toISOString().slice(0,10),ps=values(state,'pipes').filter(p=>!p.outcome&&!p.retired&&(p.date===date||p.snoozeUntil===date));return `<section class="day ${date===today()?'today':''}"><div class="day-title">${d.toLocaleDateString('pt-BR',{weekday:'short'})}<b>${d.toLocaleDateString('pt-BR',{day:'2-digit',month:'short'})}</b></div>${ps.map(p=>`<button class="agenda-card" data-edit-pipe="${esc(p.id)}" style="--cat:${cats(p.cat).color}"><strong>${esc(clientName(p))}</strong><small>${esc(p.next||cats(p.cat).name)}</small><small>${shortMoney(p.value)}${p.snoozeUntil===date?' · Retomar':''}</small></button>`).join('')||'<p class="small muted">Dia livre para conectar.</p>'}</section>`;}).join('')}</div>`;
}
function renderHistory(){const ps=Object.values(state.pipes).filter(p=>p.outcome||p.retired||p.deletedAt||(p.snoozeUntil&&p.snoozeUntil>today())).filter(p=>historyFilter==='all'||historyFilter==='trash'&&p.deletedAt||historyFilter==='legacy'&&p.retired||historyFilter===p.outcome||historyFilter==='snoozed'&&p.snoozeUntil&&p.snoozeUntil>today());
  return pageTitle('Nada se perde pelo caminho.','Negócios concluídos, pipes adiados e registros preservados.', '', 'HISTÓRICO DO RELACIONAMENTO')+`<div class="toolbar"><div class="chips">${[['all','Todos'],['Ganho','Ganhos'],['Perdido','Perdidos'],['snoozed','Adiados'],['legacy','Legado RV'],['trash','Lixeira']].map(([k,v])=>`<button class="chip ${historyFilter===k?'on':''}" data-history-filter="${k}">${v}</button>`).join('')}</div></div><div class="panel">${ps.length?ps.map(p=>`<div>${activityRow(p)}<div style="padding:0 22px 13px;text-align:right">${button('Restaurar / reabrir','restore-pipe','history','',`data-id="${esc(p.id)}"`)}</div>`).join(''):empty('Histórico em dia.','Seus pipes concluídos e movidos para a lixeira aparecem aqui.','history')}</div>`;
}
function renderSettings(){const localCount=localLegacy?migrateLegacy(localLegacy,state).addedPipes:0;return pageTitle('Sua base. Em qualquer tela.','A mesma chave abre os mesmos clientes no notebook e no iPad.','','SEU ESPAÇO PESSOAL')+`<div class="settings-grid"><section class="panel"><div class="row">${icon('key')}<h3>Acesso pessoal</h3></div><p>Seus clientes e carteiras são criptografados antes de sair deste dispositivo. Guarde a chave em um gerenciador de senhas: ela é necessária para abrir e recuperar sua base.</p>${button('Ver minha chave','show-key','key')}${button('Sincronizar agora','sync','cloud','','style="margin-top:10px"')}<p><span class="sync ${syncStatus}" data-sync><i class="dot"></i>${statusLabel()}</span></p></section><section class="panel"><div class="row">${icon('history')}<h3>Trazer os pipes antigos</h3></div><p>${localCount?`${localCount} pipes encontrados neste dispositivo para transferir.`:'Use o dispositivo em que cadastrou os pipes, o antigo código de nuvem ou um arquivo de backup.'} A importação acrescenta registros e preserva uma cópia original.</p>${button('Importar deste dispositivo','import-local','download')}${button('Usar código antigo','import-code','cloud','','style="margin-top:10px"')}</section><section class="panel"><div class="row">${icon('download')}<h3>Cópia de segurança</h3></div><p>Exporte sua base completa, incluindo clientes, carteiras, pipes, metas e histórico. O arquivo exportado contém os dados legíveis; guarde-o em um local pessoal.</p>${button('Exportar minha base','export','download')}${button('Importar arquivo','import-file','upload','','style="margin-top:10px"')}<input id="backupFile" type="file" accept=".json,application/json" hidden></section><section class="panel"><div class="row">${icon('pie')}<h3>Classes de investimento</h3></div><p>As classes vieram do Hub do Assessor. Renda variável continua disponível na carteira, embora não exista mais como categoria de novos pipes.</p><div class="chips">${classList().map(c=>`<span class="pill">${esc(classLabel(c))}</span>`).join('')}</div>${button('Adicionar classe','new-class','plus','','style="margin-top:18px"')}</section></div>`;}
const classList=()=>Array.isArray(state.settings.classes)?state.settings.classes:state.settings.classes?.items||CLASSES;
function renderWelcome(){app.innerHTML=`<div class="welcome"><section class="welcome-story">${brand()}<div><div class="eyebrow">MAIS CONTEXTO. MAIS CONEXÃO.</div><h1>Seu próximo passo<br>começa em<br><em>cada cliente.</em></h1><p>Carteiras, potenciais e oportunidades. Tudo o que importa para cuidar de cada relacionamento, no mesmo lugar.</p><div class="welcome-features"><span>${icon('grip')}Pipes que acompanham o seu toque.</span><span>${icon('pie')}Uma carteira. Todas as instituições.</span><span>${icon('cloud')}A mesma base no iPad e no notebook.</span></div></div><footer>RICO · SEU ESPAÇO DE RELACIONAMENTO</footer></section><section class="welcome-form"><div class="eyebrow">BEM-VINDO AO SEU ESPAÇO</div><h2>Vamos continuar?</h2><p>Abra sua base com a chave pessoal. Primeiro acesso? Crie sua base e transfira os pipes que você já cadastrou.</p><form id="unlockForm"><label class="field">Sua chave de acesso<input name="key" type="password" autocomplete="current-password" placeholder="RICO-…" required spellcheck="false" autocapitalize="off"></label><label class="field-check"><input name="remember" type="checkbox">Lembrar neste dispositivo pessoal</label><div class="form-error" role="alert"></div><button class="btn green" type="submit">${icon('lock')}Abrir minha base</button></form><div class="divider">ou comece por aqui</div>${button('Criar minha base privada','create-vault','plus')}${button('Explorar a demonstração','demo','arrow')}<div class="welcome-footer">Sua chave dá acesso aos seus dados. Use a mesma em todos os dispositivos e não a compartilhe. Os pipes antigos continuam preservados no dispositivo de origem.</div></section></div>`;$('#unlockForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,data=new FormData(form);await formAction(form,()=>openVault(data.get('key'),false,data.get('remember')==='on'));};}
async function openVault(key,create=false,remember=false){
  const next=new VaultStore({onChange:s=>{state=s;if(store===next)render();},onStatus:setStatus});
  try{await next.open(key,{create});}catch(e){await next.close();throw e;}
  store=next;accessKey=key.trim();demo=false;state=next.state;screen='board';clientId=null;
  sessionStorage.setItem('ricoCRM.access',accessKey);if(remember)localStorage.setItem('ricoCRM.access',accessKey);else localStorage.removeItem('ricoCRM.access');
  render();
  localLegacy=await readLegacyLocal();
  const pending=migrateLegacy(localLegacy,state);
  if(pending.addedPipes){await save(pending.operations);notify(`${pending.addedPipes} pipes preservados e vinculados aos clientes. Originais mantidos.`);}
  // The old application is never written to. Its cloud code is only read by explicit migration.
}
async function save(ops){const list=Array.isArray(ops)?ops:[ops];if(demo){state=applyOperations(state,list);render();return;}await store.commit(list);}
function patch(type,id,data){return {type,id,patch:{...data,updatedAt:new Date().toISOString()}};}
function showModal(title,body,submit,label='Salvar',extra=''){
  if(dialog.open)dialog.close();dialog.innerHTML=`<form id="modalForm"><div class="dialog-head"><h2 id="dialogTitle">${title}</h2><button type="button" class="icon-btn" data-action="close-modal" aria-label="Fechar">${icon('close')}</button></div><div class="dialog-body">${body}<div class="form-error" role="alert"></div></div><div class="dialog-foot">${extra}<button type="button" class="btn" data-action="close-modal">Cancelar</button><button type="submit" class="btn primary">${label}</button></div></form>`;dialog.showModal();$('#modalForm').onsubmit=async e=>{e.preventDefault();await formAction(e.currentTarget,async()=>{await submit(new FormData(e.currentTarget));if(dialog.open)dialog.close();});};
}
async function formAction(form,fn){const b=form.querySelector('[type=submit]'),err=form.querySelector('.form-error');if(b)b.disabled=true;if(err)err.textContent='';try{await fn();}catch(e){if(err)err.textContent=e.message||'Não foi possível salvar. Tente novamente.';else notify(e.message);}finally{if(b)b.disabled=false;}}
const field=(label,name,value='',type='text',full=false,attrs='')=>`<label class="field ${full?'full':''}">${label}<input name="${name}" value="${esc(value)}" type="${type}" ${attrs}></label>`;
const selectField=(label,name,arr,current,full=false)=>`<label class="field ${full?'full':''}">${label}<select name="${name}">${options(arr,current)}</select></label>`;
function editClient(id=null){const c=state.clients[id]||{},pot=c.potentials||{};
  showModal(id?'Cuidar do relacionamento':'Adicionar cliente',`<div class="fields">${field('Nome do cliente','name',c.name,'text',true,'required maxlength="140" autocomplete="name"')}${field('Telefone','phone',c.phone,'tel',false,'autocomplete="tel"')}${field('E-mail','email',c.email,'email',false,'autocomplete="email"')}${selectField('Perfil de investimento','profile',['Não informado','Conservador','Moderado','Arrojado'],c.profile||'Não informado')}${selectField('Classificação do cliente','tier',[{id:'',name:'A classificar'},...['A','B','C','D'].map(t=>({id:t,name:'Classe '+t}))],c.tier||'')}<p class="field full small muted">Classificação manual do cliente, independente da prioridade dos pipes.</p><div class="field full"><span class="eyebrow">POTENCIAL DE RELACIONAMENTO</span></div>${CATEGORIES.map(cat=>selectField(cat.name,'potential-'+cat.id,['A mapear','Alto','Médio','Baixo','Sem potencial'],pot[cat.id]||'A mapear')).join('')}<label class="field full">Objetivos e observações<textarea name="notes" maxlength="10000">${esc(c.notes)}</textarea></label></div>`,async f=>{const name=f.get('name').trim();if(!name)throw Error('Informe o nome do cliente.');const target=id||uid();await save(patch('clients',target,{id:target,name,phone:f.get('phone').trim(),email:f.get('email').trim(),profile:f.get('profile'),tier:f.get('tier'),notes:f.get('notes'),potentials:Object.fromEntries(CATEGORIES.map(cat=>[cat.id,f.get('potential-'+cat.id)])),createdAt:c.createdAt||new Date().toISOString()}));if(!id){clientId=target;screen='clients';detailTab='wallet';render();}notify('Cliente salvo.');});
}
function editPipe(id=null,cat='cap',forClient=null){
  if(!values(state,'clients').length){editClient();notify('Cadastre o cliente para vincular sua primeira oportunidade.');return;}
  const p=state.pipes[id]||{},cs=values(state,'clients').sort((a,b)=>a.name.localeCompare(b.name));const categoryOptions=p.retired?[...CATEGORIES,{id:p.cat,name:cats(p.cat).name}]:CATEGORIES;
  showModal(id?'Detalhes da oportunidade':'Nova oportunidade',`<div class="fields">${selectField('Cliente','clientId',cs.map(c=>({id:c.id,name:c.name})),p.clientId||forClient||cs[0].id,true)}${field('Nome da oportunidade','title',p.title||'','text',true,'maxlength="180" placeholder="Ex.: Transferência da carteira C6"')}${selectField('Categoria','cat',categoryOptions,p.cat||cat)}${field('Valor (R$)','value',p.value??'','number',false,'min="0" step="0.01" required inputmode="decimal"')}${selectField('Etapa','stage',STAGES,STAGES.includes(p.stage)?p.stage:STAGES[0])}${field('Data do próximo passo','date',p.date||today(),'date')}${selectField('Subtipo de captação','subtype',[{id:'',name:'Não se aplica'},...SUBTYPES.map(x=>({id:x,name:x}))],p.subtype||'')}${field('Prioridade de 0 a 10','nota',p.nota??5,'number',false,'min="0" max="10" step="1" required inputmode="numeric"')}${field('Próximo passo','next',p.next,'text',true,'maxlength="300" placeholder="Ex.: Conversar sobre a transferência"')}${field('Adiar / retomar em (opcional)','snoozeUntil',p.snoozeUntil||'','date',true)}<label class="field full">Observações<textarea name="notes" maxlength="10000">${esc(p.notes)}</textarea></label><label class="field full">Tipos de alocação (separados por vírgula)<input name="alloc" value="${esc((p.alloc||[]).join(', '))}" placeholder="RF, Recorrentes, COE"></label>${id?`<div class="field full"><p class="muted small">${p.retired?'Registro legado preservado. Escolha uma das quatro novas categorias para reativá-lo.':''}${p.outcome?'Resultado: '+esc(p.outcome):''}${p.deletedAt?' · Este pipe está na lixeira.':''}</p></div>`:''}</div>`,async f=>{
    const target=id||uid(),client=state.clients[f.get('clientId')],nextCat=f.get('cat');if(!client)throw Error('Escolha um cliente válido.');const val=Number(f.get('value')),nota=Number(f.get('nota'));if(!Number.isFinite(val)||val<0||nota<0||nota>10)throw Error('Confira o valor e a prioridade.');
    await save(patch('pipes',target,{id:target,clientId:client.id,client:client.name,title:f.get('title').trim(),cat:nextCat,value:val,stage:f.get('stage'),date:f.get('date'),subtype:f.get('subtype'),nota,next:f.get('next').trim(),notes:f.get('notes'),alloc:f.get('alloc').split(',').map(x=>x.trim()).filter(Boolean),snoozeUntil:f.get('snoozeUntil')||null,retired:!CATEGORIES.some(c=>c.id===nextCat),createdAt:p.createdAt||new Date().toISOString()}));notify('Oportunidade salva.');
  },'Salvar pipe',id?`<button type="button" class="btn danger" data-action="pipe-actions" data-id="${esc(id)}">Mover / concluir</button>`:'');
}
function editAsset(id=null){const a=state.assets[id]||{};showModal(id?'Editar posição':'Adicionar à carteira',`<div class="fields">${field('Instituição','institution',a.institution||'Rico','text',true,'required maxlength="100" list="institutions"')}<datalist id="institutions"><option value="Rico"><option value="C6"><option value="Itaú"><option value="BTG"><option value="XP"><option value="Bradesco"><option value="Santander"><option value="Nubank"></datalist>${field('Investimento ou descrição','name',a.name||'','text',true,'maxlength="160" placeholder="Ex.: Saldo informado, CDB, fundo…"')}${selectField('Classe de investimento','class',classList().map(c=>({id:c,name:classLabel(c)})),a.class||'Não informado')}${field('Valor atual (R$)','value',a.value??'','number',false,'min="0.01" step="0.01" required inputmode="decimal"')}${field('Data da informação','asOf',a.asOf||today(),'date',true,'required')}<label class="field full">Observações<textarea name="notes" maxlength="5000">${esc(a.notes)}</textarea><small>Ao detalhar um saldo geral, ajuste ou remova a posição anterior para não contar o mesmo patrimônio duas vezes.</small></label></div>`,async f=>{const value=Number(f.get('value')),institution=f.get('institution').trim();if(!institution||!Number.isFinite(value)||value<=0)throw Error('Informe a instituição e um valor maior que zero.');const target=id||uid();await save(patch('assets',target,{id:target,clientId:a.clientId||clientId,institution,name:f.get('name').trim(),class:f.get('class'),value,asOf:f.get('asOf'),notes:f.get('notes')}));notify('Carteira atualizada.');},'Salvar posição',id?`<button type="button" class="btn danger" data-action="remove-asset" data-id="${esc(id)}">Remover</button>`:'');}
function pipeActions(id){const p=state.pipes[id];if(!p)return;showModal('Mover oportunidade',`<p class="muted small" style="margin-bottom:20px">${esc(clientName(p))} · ${money(p.value)}</p><div class="fields">${selectField('Destino','destination',[...CATEGORIES,{id:'won',name:'Concluir como ganho'},{id:'lost',name:'Concluir como perdido'},{id:'trash',name:'Mover para a lixeira'}],p.cat,true)}${field('Data da conclusão (se ganho/perdido)','closedDate',today(),'date',true)}</div>`,async f=>{await movePipe(id,f.get('destination'),f.get('closedDate'));},'Mover pipe');}
async function movePipe(id,destination,closedDate=today(),order){
  const p=state.pipes[id];if(!p)return;
  const keys=['cat','deletedAt','outcome','closedAt','retired','order','snoozeUntil'];const previous=Object.fromEntries(keys.map(k=>[k,p[k]??null]));
  let changes;if(destination==='trash')changes={deletedAt:new Date().toISOString()};else if(['won','lost'].includes(destination))changes={outcome:destination==='won'?'Ganho':'Perdido',closedAt:(closedDate||today())+'T12:00:00',deletedAt:null};else changes={cat:destination,outcome:null,closedAt:null,deletedAt:null,retired:false,snoozeUntil:null,...(order===undefined?{}:{order})};
  await save(patch('pipes',id,changes));notify(destination==='trash'?'Pipe movido para a lixeira.':destination==='won'?'Negócio ganho. Meta atualizada.':destination==='lost'?'Resultado registrado no histórico.':'Pipe movido para '+cats(destination).name,()=>save(patch('pipes',id,previous)));
}
function editGoals(){const g=state.settings.goals;showModal('Metas mensais',`<div class="fields">${CATEGORIES.map(c=>field(c.name+' (R$)',c.id,g[c.id==='ag'?'aloc':c.id],'number',false,'min="0" step="0.01" required')).join('')}<p class="small muted field full">A meta da cesta MEREO continua em R$ 2,2 mi, conforme o app anterior. As metas acima controlam os cartões mensais.</p></div>`,async f=>{await save(patch('settings','goals',Object.fromEntries(CATEGORIES.map(c=>[c.id==='ag'?'aloc':c.id,Number(f.get(c.id))]))));notify('Metas atualizadas.');});}
function editResults(){const m=monthData(state,month);showModal('Realizado · '+monthLabel(),`<div class="fields"><p class="small muted field full">Os valores abaixo são adicionais aos pipes ganhos. Para o MEREO, os campos de substituição são opcionais.</p>${CATEGORIES.map(c=>field(c.name+' adicional (R$)',c.id,m.manual[c.id==='ag'?'aloc':c.id]||0,'number',false,'step="0.01"')).join('')}${field('Cartões (pontos)','cards',m.mm.cards||0,'number',false,'min="0" step="1"')}${field('Índice comercial (%)','ic',m.mm.ic??'','number',false,'min="0" max="100" step="0.01"')}${field('NPS','nps',m.mm.nps??'','number',false,'min="-100" max="100" step="0.01"')}<span></span>${[['ovCap','Substituir captação MEREO'],['ovAloc','Substituir alocação MEREO'],['ovSeg','Substituir seguros MEREO'],['ovCon','Substituir consórcio MEREO']].map(([k,t])=>field(t+' (R$)',k,m.mm[k]??'','number',false,'step="0.01"')).join('')}</div>`,async f=>{const manual={...m.manual,...Object.fromEntries(CATEGORIES.map(c=>[c.id==='ag'?'aloc':c.id,Number(f.get(c.id))]))},mm={...m.mm};for(const k of ['cards','ic','nps','ovCap','ovAloc','ovSeg','ovCon'])mm[k]=f.get(k)===''?null:Number(f.get(k));await save([patch('settings','manual',{[m.key]:manual}),patch('settings','mereo',{[m.key]:mm})]);notify('Resultados atualizados.');});}
async function importSource(source){
  if(source?.version===3){const ops=importBase(source,state);
    showModal('Importar base de clientes',`<p class="notes">${Object.keys(source.clients).length} clientes e ${Object.keys(source.pipes).length} pipes no arquivo. Registros que já existem serão mantidos; apenas os novos serão adicionados.</p>`,async()=>{await save(ops);notify('Base importada sem substituir registros existentes.');},'Adicionar à minha base');return;
  }
  const result=migrateLegacy(source,state);if(!result.total)throw Error('Nenhum pipe compatível encontrado neste backup.');
  showModal('Seus pipes, no novo modelo',`<div class="notice">${icon('shield')}<span>O original permanece preservado. Esta importação não substitui sua base.</span></div><p class="notes">${result.addedPipes} pipes a adicionar<br>${result.addedClients} clientes a criar<br>${result.retired} pipes de categorias antigas ficam no histórico.<br><br>Valores, datas, etapas, notas e resultados acompanham cada registro.</p>`,async()=>{await save(result.operations);notify(`${result.addedPipes} pipes transferidos.`);},'Transferir pipes');
}
function download(data,name){const url=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function createVault(){const key=generateKey();showModal('Guarde sua chave pessoal',`<p class="notes" style="margin-bottom:18px">Esta chave abre sua base em todos os seus dispositivos. Salve-a no seu gerenciador de senhas antes de continuar. Não existe recuperação sem a chave.</p><div class="key">${esc(key)}</div><button type="button" class="btn" id="copyNewKey" style="margin:15px 0">${icon('key')}Copiar chave</button><label class="field-check"><input type="checkbox" name="saved" required>Guardei minha chave em um lugar seguro.</label><label class="field-check" style="margin-top:12px"><input type="checkbox" name="remember">Lembrar neste dispositivo pessoal</label>`,async f=>{await openVault(key,true,f.get('remember')==='on');notify('Base criada. Use esta mesma chave no outro dispositivo.');},'Criar e abrir minha base');$('#copyNewKey').onclick=async()=>{try{await navigator.clipboard.writeText(key);$('#copyNewKey').textContent='Chave copiada';}catch{$('#copyNewKey').textContent='Selecione e copie a chave acima';}};}
function showKey(){if(demo){notify('A demonstração não tem uma chave de acesso.');return;}showModal('Sua chave pessoal',`<p class="notes" style="margin-bottom:18px">Cole esta mesma chave no iPad ou notebook para abrir seus clientes e pipes. Mantenha-a privada.</p><div class="key">${esc(accessKey)}</div>`,async()=>{await navigator.clipboard.writeText(accessKey);notify('Chave copiada.');},'Copiar chave');}
async function lock(){if(drag)endDrag(true);const previous=store;store=null;demo=false;accessKey='';sessionStorage.removeItem('ricoCRM.access');localStorage.removeItem('ricoCRM.access');if(previous)await previous.close();state=emptyState();if(dialog.open)dialog.close();renderWelcome();}
function demoData(){const s=emptyState(),names=['Ana Martins','Bruno Costa','Camila Rocha','Daniel Oliveira','Elisa Andrade','Felipe Santos'];const prof=['Moderado','Arrojado','Conservador'];names.forEach((name,i)=>{const id='demo-c'+i;s.clients[id]={id,name,profile:prof[i%3],tier:['A','B','A','C','B','D'][i],phone:'',email:'',notes:'Cliente fictício, criado exclusivamente para demonstrar a nova experiência.',potentials:{cap:i%2?'Médio':'Alto',ag:'Alto',seg:i%3?'Médio':'Alto',con:i%2?'Baixo':'Alto'}};});
  const templates=[['demo-c0','cap',200000,'Transferência da carteira C6',9,'TED'],['demo-c1','cap',350000,'Consolidar investimentos',7,'STVM'],['demo-c4','cap',80000,'Portabilidade previdenciária',5,'Previdência'],['demo-c2','ag',150000,'Reorganizar renda fixa',8,''],['demo-c5','ag',95000,'Diversificar investimentos',6,''],['demo-c0','seg',12000,'Proteção familiar',9,''],['demo-c3','seg',18000,'Seguro de vida',6,''],['demo-c4','con',250000,'Planejar o próximo imóvel',8,''],['demo-c1','con',150000,'Aquisição de veículo',4,'']];
  templates.forEach(([clientId,cat,value,title,nota,subtype],i)=>{const id='demo-p'+i,d=new Date(today()+'T12:00:00');d.setDate(d.getDate()+i%5-1);s.pipes[id]={id,clientId,cat,value,title,nota,subtype,stage:STAGES[i%6],date:d.toISOString().slice(0,10),next:['Enviar proposta','Agendar conversa','Acompanhar decisão'][i%3],notes:''};});
  [['Rico','Renda Fixa',280000,'CDB e Tesouro'],['C6','Renda Fixa',200000,'Saldo informado'],['Rico','Previdência',150000,'Plano previdenciário'],['Rico','Fundos Listados',70000,'Fundos imobiliários'],['BTG','Internacional',100000,'Carteira internacional']].forEach(([institution,cls,value,name],i)=>{s.assets['demo-a'+i]={id:'demo-a'+i,clientId:'demo-c0',institution,class:cls,value,name,asOf:today()};});return s;}
const actions={
  'demo':()=>{demo=true;state=demoData();screen='board';clientId=null;render();},'lock':lock,'create-vault':createVault,'close-modal':()=>dialog.close(),
  'new-client':()=>editClient(),'edit-client':()=>editClient(clientId),'new-pipe':()=>editPipe(),'client-pipe':()=>editPipe(null,'cap',clientId),'back-clients':()=>{clientId=null;render();},
  'new-asset':()=>editAsset(),'edit-goals':editGoals,'edit-results':editResults,'show-key':showKey,'sync':async()=>{if(store){await store.sync();notify(syncStatus==='synced'?'Base sincronizada.':'Alterações preservadas no dispositivo. A conexão será tentada novamente.');}},
  'week-prev':()=>{weekOffset--;render();},'week-next':()=>{weekOffset++;render();},'week-today':()=>{weekOffset=0;render();},
  'export':()=>{download({...state,exportedAt:new Date().toISOString()},'rico-clientes-'+today()+'.json');notify('Cópia completa exportada.');},
  'import-local':async()=>{if(demo){notify('Saia da demonstração para importar seus dados reais.');return;}localLegacy=await readLegacyLocal();await importSource(localLegacy);},
  'import-code':()=>{if(demo){notify('Abra sua base para importar dados reais.');return;}showModal('Recuperar nuvem antiga',field('Código do app anterior','code',localStorage.getItem('ricoPipeline.cloudId')||'','text',true,'required placeholder="XXXX-XXXX-XXXX"'),async f=>{const source=await new FirestoreTransport().legacy(f.get('code').trim().toUpperCase());dialog.close();setTimeout(()=>importSource(source).catch(e=>notify(e.message)),0);},'Buscar backup');},
  'import-file':()=>$('#backupFile')?.click(),
  'new-class':()=>showModal('Nova classe de investimento',field('Nome da classe','name','','text',true,'required maxlength="80"'),async f=>{const name=f.get('name').trim();if(!name)throw Error('Informe o nome da classe.');await save(patch('settings','classes',{items:[...new Set([...classList(),name])]}));notify('Classe adicionada.');}),
  'pipe-actions':el=>pipeActions(el.dataset.id),
  'restore-pipe':el=>{const p=state.pipes[el.dataset.id];if(p.retired){editPipe(p.id);return;}return movePipe(p.id,p.cat);},
  'remove-asset':async el=>{const id=el.dataset.id,old=state.assets[id];await save(patch('assets',id,{deletedAt:new Date().toISOString()}));dialog.close();notify('Posição removida.',()=>save(patch('assets',id,{deletedAt:old.deletedAt||null})));}
};
document.addEventListener('click',async e=>{
  const el=e.target.closest('button');if(!el)return;
  try{
    if(el.dataset.action){await actions[el.dataset.action]?.(el);return;}
    if(el.dataset.nav){screen=el.dataset.nav;clientId=null;search='';filter='all';clientPotential='all';render();return;}
    if(el.dataset.client){clientId=el.dataset.client;screen='clients';detailTab='wallet';render();return;}
    if(el.dataset.editPipe){editPipe(el.dataset.editPipe);return;}
    if(el.dataset.editAsset){editAsset(el.dataset.editAsset);return;}
    if(el.dataset.newCat){editPipe(null,el.dataset.newCat);return;}
    if(el.dataset.filter){filter=el.dataset.filter;render();return;}
    if(el.dataset.historyFilter){historyFilter=el.dataset.historyFilter;render();return;}
    if(el.dataset.tab){detailTab=el.dataset.tab;render();return;}
    if(el.dataset.group){groupWallet=el.dataset.group;render();return;}
    if(el.dataset.drag&&!drag&&!suppressGripClick){pipeActions(el.dataset.drag);}
  }catch(err){notify(err.message);}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;render();}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='dateFilter'){dateFilter=el.value;render();}if(el.id==='subtypeFilter'){subtypeFilter=el.value;render();}if(el.id==='clientPotential'){clientPotential=el.value;render();}if(el.id==='goalMonth'&&el.value){month=el.value;render();}if(el.id==='backupFile'&&el.files[0]){if(demo){notify('Abra sua base para importar dados reais.');return;}try{if(el.files[0].size>4000000)throw Error('Arquivo muito grande para esta base.');await importSource(JSON.parse(await el.files[0].text()));}catch(err){notify(err.message);}finally{el.value='';}}});
let suppressGripClick=false;
function startDrag(e){const grip=e.target.closest('[data-drag]');if(!grip||e.button!==0||e.isPrimary===false)return;
  drag={id:grip.dataset.drag,pointerId:e.pointerId,grip,startX:e.clientX,startY:e.clientY,x:e.clientX,y:e.clientY,active:false,target:null,frame:null};
  grip.setPointerCapture(e.pointerId);
}
function activateDrag(){if(!drag||drag.active)return;drag.active=true;document.body.classList.add('dragging');const card=drag.grip.closest('.pipe-card');drag.card=card;drag.ghost=card.cloneNode(true);drag.ghost.classList.add('drag-ghost');drag.ghost.removeAttribute('data-pipe');drag.ghost.querySelectorAll('button').forEach(b=>b.tabIndex=-1);drag.ghost.setAttribute('aria-hidden','true');document.body.append(drag.ghost);card.classList.add('drag-source');const targets=$('#dragTargets');targets.innerHTML=`${CATEGORIES.map(c=>`<div class="drop-target" data-drop="${c.id}">${icon(c.icon)}${c.name}</div>`).join('')}<div class="drop-target" data-drop="won">${icon('check')}Ganho</div><div class="drop-target trash" data-drop="trash">${icon('trash')}Lixeira</div>`;targets.classList.add('show');targets.setAttribute('aria-hidden','false');$('#dragLive').textContent='Arrastando. Escolha uma categoria, Ganho ou Lixeira.';dragTick();}
function updateDrag(e){if(!drag||e.pointerId!==drag.pointerId)return;drag.x=e.clientX;drag.y=e.clientY;if(!drag.active&&Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>7)activateDrag();if(drag.active)e.preventDefault();}
function dragTick(){if(!drag?.active)return;const d=drag;d.ghost.style.left=Math.min(innerWidth-250,Math.max(5,d.x-110))+'px';d.ghost.style.top=Math.max(10,d.y-50)+'px';
  const target=document.elementFromPoint(d.x,d.y)?.closest('[data-drop]');if(target!==d.target){d.target?.classList.remove('drop-over');d.target=target;target?.classList.add('drop-over');if(target)$('#dragLive').textContent='Soltar em '+(target.dataset.drop==='trash'?'Lixeira':target.dataset.drop==='won'?'Ganho':cats(target.dataset.drop).name);}
  const board=$('.board');if(board){const r=board.getBoundingClientRect();if(d.y>r.top&&d.y<r.bottom){if(d.x>r.right-48)board.scrollLeft+=12;else if(d.x<r.left+48)board.scrollLeft-=12;}
    const col=document.elementFromPoint(d.x,d.y)?.closest('.column')?.querySelector('.column-body');if(col){const r=col.getBoundingClientRect();if(d.y>r.bottom-50)col.scrollTop+=9;else if(d.y<r.top+50)col.scrollTop-=9;}}
  d.frame=requestAnimationFrame(dragTick);
}
async function endDrag(cancelled=false){if(!drag)return;const d=drag;drag=null;cancelAnimationFrame(d.frame);try{if(d.grip.hasPointerCapture(d.pointerId))d.grip.releasePointerCapture(d.pointerId);}catch{}d.ghost?.remove();d.card?.classList.remove('drag-source');d.target?.classList.remove('drop-over');document.body.classList.remove('dragging');$('#dragTargets').classList.remove('show');$('#dragTargets').setAttribute('aria-hidden','true');
  if(d.active){suppressGripClick=true;setTimeout(()=>suppressGripClick=false,300);if(!cancelled&&d.target){try{await movePipe(d.id,d.target.dataset.drop);}catch(e){notify(e.message);}}else $('#dragLive').textContent='Movimento cancelado.';}
  if(renderDeferred){renderDeferred=false;render();}
}
document.addEventListener('pointerdown',startDrag);document.addEventListener('pointermove',updateDrag,{passive:false});document.addEventListener('pointerup',e=>{if(drag?.pointerId===e.pointerId)endDrag(false);});document.addEventListener('pointercancel',()=>endDrag(true));document.addEventListener('lostpointercapture',()=>{if(drag)endDrag(true);});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&drag)endDrag(true);});
window.addEventListener('online',()=>store?.sync());window.addEventListener('focus',()=>store?.sync());document.addEventListener('visibilitychange',()=>{if(!document.hidden)store?.sync();else if(drag)endDrag(true);});
async function boot(){renderWelcome();try{const remembered=sessionStorage.getItem('ricoCRM.access')||localStorage.getItem('ricoCRM.access');if(remembered)await openVault(remembered,false,!!localStorage.getItem('ricoCRM.access'));}catch(e){renderWelcome();notify(e.message);}if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}
boot();
